    "patient_family_realworld_adaptation": "excellent"
  },
  "high_order_assessment": [
    {
      "active_model_action": true,
      "citations": [
        {
          "event_id": "lite_evt_00112",
          "explanation": "Doctor builds a concrete medication-scheduling workflow for the caregiver: grouping drops into four daily time blocks, spacing 5–10 minutes, and handling special formulations.",
          "quote": "可以按早、午、晚、睡前分成4组，每组依次间隔5–10分钟"
        },
        {
          "event_id": "lite_evt_00135",
          "explanation": "Doctor provides a specific diagram-like plan (breakfast/noon/dinner/bedtime) for the three-bottle regimen, with explicit safety rules about not adding doses.",
          "quote": "按早饭后、中午、晚饭后、睡前四组执行：每瓶每次1滴，间隔约10分钟"
        }
      ],
      "completion": "complete",
      "explanation": "HO4 requires converting the unreadable-document barrier into a concrete caregiver-executable system. The doctor does this by first asking the family to re-read the bottle labels, then building a detailed four-group daily drop schedule with spacing, hand-washing, no-touch rules, and a contingency plan for hormonal drops—far beyond merely saying 'ask the hospital.'",
      "ho_id": "HO4",
